CREATE TABLE [dbo].[ccPosicion](	  [pos_id] INT NOT NULL IDENTITY(1,1)	, [Computer] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [ext_id] SMALLINT NOT NULL	, [user_id] SMALLINT NOT NULL DEFAULT((0))	, [Status] VARCHAR(8) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT((1))	, [tipoConexion] TINYINT NOT NULL DEFAULT((0))	, [IP] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, CONSTRAINT [PK_ccPosicion] PRIMARY KEY ([pos_id] ASC))CREATE NONCLUSTERED INDEX [IX_ccPosicion] ON [dbo].[ccPosicion] ([Computer] ASC)CREATE NONCLUSTERED INDEX [IX_ccPosicion_1] ON [dbo].[ccPosicion] ([ext_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccPosicion_2] ON [dbo].[ccPosicion] ([user_id] ASC, [Computer] ASC)